import React, { useState, useEffect } from "react";
import {
  Box,
  Typography,
  Paper,
  Grid,
  Card,
  CardContent,
  CircularProgress,
  Button,
  Tabs,
  Tab,
} from "@mui/material";
import {
  Security,
  TrendingUp,
  Warning,
  CheckCircle,
  Cancel,
  Assessment,
  AccountBalance,
  CreditCard,
  Person,
  Payment,
} from "@mui/icons-material";
import { flaggedAPI } from "../services/api";

const Dashboard = ({ onShowSnackbar }) => {
  const [stats, setStats] = useState({
    totalFlagged: 0,
    pendingReview: 0,
    confirmedFraud: 0,
    verifiedSafe: 0,
    highRiskCount: 0,
    flaggedByType: {},
    recentActivity: [],
  });
  const [loading, setLoading] = useState(true);
  const [selectedTab, setSelectedTab] = useState(0);

  const loadStats = async () => {
    try {
      setLoading(true);
      const response = await flaggedAPI.getStats();
      setStats(response.data);
    } catch (error) {
      // If stats API is not available, use default values
      console.warn("Stats API not available, using default values");
      setStats({
        totalFlagged: 0,
        pendingReview: 0,
        confirmedFraud: 0,
        verifiedSafe: 0,
        highRiskCount: 0,
        flaggedByType: {
          transactions: 0,
          loan_requests: 0,
          credit_history: 0,
          kyc: 0,
          repayments: 0,
        },
        recentActivity: [],
      });
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadStats();
  }, []);

  const fraudDetectionTypes = [
    {
      key: "transactions",
      label: "Transactions",
      icon: AccountBalance,
      color: "#1976d2",
    },
    {
      key: "loan_requests",
      label: "Loan Requests",
      icon: CreditCard,
      color: "#388e3c",
    },
    {
      key: "credit_history",
      label: "Credit History",
      icon: Assessment,
      color: "#f57c00",
    },
    { key: "kyc", label: "KYC Data", icon: Person, color: "#7b1fa2" },
    { key: "repayments", label: "Repayments", icon: Payment, color: "#d32f2f" },
  ];

  if (loading) {
    return (
      <Box
        sx={{
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          minHeight: 400,
        }}
      >
        <CircularProgress />
      </Box>
    );
  }

  return (
    <Box>
      {/* Header */}
      <Box sx={{ mb: 3 }}>
        <Typography
          variant='h4'
          sx={{ fontWeight: "bold", color: "#424242", mb: 1 }}
        >
          Fraud Detection Dashboard
        </Typography>
        <Typography variant='body1' color='text.secondary'>
          Overview of fraud detection system performance and flagged items
          across all data types.
        </Typography>
      </Box>

      {/* Main Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ borderRadius: 2, boxShadow: 2, height: "100%" }}>
            <CardContent>
              <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                <Box
                  sx={{
                    p: 1,
                    borderRadius: 2,
                    bgcolor: "#ffebee",
                    color: "#d32f2f",
                    mr: 2,
                  }}
                >
                  <Security sx={{ fontSize: 24 }} />
                </Box>
                <Typography
                  variant='h6'
                  sx={{ fontWeight: "bold", color: "#424242" }}
                >
                  Total Flagged
                </Typography>
              </Box>
              <Typography
                variant='h3'
                sx={{ fontWeight: "bold", color: "#d32f2f", mb: 1 }}
              >
                {stats.totalFlagged}
              </Typography>
              <Typography variant='body2' color='text.secondary'>
                Items requiring review
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ borderRadius: 2, boxShadow: 2, height: "100%" }}>
            <CardContent>
              <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                <Box
                  sx={{
                    p: 1,
                    borderRadius: 2,
                    bgcolor: "#fff3e0",
                    color: "#f57c00",
                    mr: 2,
                  }}
                >
                  <Warning sx={{ fontSize: 24 }} />
                </Box>
                <Typography
                  variant='h6'
                  sx={{ fontWeight: "bold", color: "#424242" }}
                >
                  Pending Review
                </Typography>
              </Box>
              <Typography
                variant='h3'
                sx={{ fontWeight: "bold", color: "#f57c00", mb: 1 }}
              >
                {stats.pendingReview}
              </Typography>
              <Typography variant='body2' color='text.secondary'>
                Awaiting verification
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ borderRadius: 2, boxShadow: 2, height: "100%" }}>
            <CardContent>
              <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                <Box
                  sx={{
                    p: 1,
                    borderRadius: 2,
                    bgcolor: "#ffebee",
                    color: "#d32f2f",
                    mr: 2,
                  }}
                >
                  <Cancel sx={{ fontSize: 24 }} />
                </Box>
                <Typography
                  variant='h6'
                  sx={{ fontWeight: "bold", color: "#424242" }}
                >
                  Confirmed Fraud
                </Typography>
              </Box>
              <Typography
                variant='h3'
                sx={{ fontWeight: "bold", color: "#d32f2f", mb: 1 }}
              >
                {stats.confirmedFraud}
              </Typography>
              <Typography variant='body2' color='text.secondary'>
                Verified fraudulent items
              </Typography>
            </CardContent>
          </Card>
        </Grid>

        <Grid item xs={12} sm={6} md={3}>
          <Card sx={{ borderRadius: 2, boxShadow: 2, height: "100%" }}>
            <CardContent>
              <Box sx={{ display: "flex", alignItems: "center", mb: 2 }}>
                <Box
                  sx={{
                    p: 1,
                    borderRadius: 2,
                    bgcolor: "#e8f5e8",
                    color: "#388e3c",
                    mr: 2,
                  }}
                >
                  <CheckCircle sx={{ fontSize: 24 }} />
                </Box>
                <Typography
                  variant='h6'
                  sx={{ fontWeight: "bold", color: "#424242" }}
                >
                  Verified Safe
                </Typography>
              </Box>
              <Typography
                variant='h3'
                sx={{ fontWeight: "bold", color: "#388e3c", mb: 1 }}
              >
                {stats.verifiedSafe}
              </Typography>
              <Typography variant='body2' color='text.secondary'>
                Legitimate transactions
              </Typography>
            </CardContent>
          </Card>
        </Grid>
      </Grid>

      {/* Detection Types Overview with Tabs */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid item xs={12}>
          <Paper sx={{ borderRadius: 2, boxShadow: 2, overflow: "hidden" }}>
            <Box sx={{ p: 3, borderBottom: "1px solid #e0e0e0" }}>
              <Typography
                variant='h6'
                sx={{ fontWeight: "bold", color: "#424242", mb: 1 }}
              >
                Fraud Detection by Data Type
              </Typography>
              <Typography variant='body2' color='text.secondary'>
                Flagged items breakdown across different data categories
              </Typography>
            </Box>

            <Box>
              <Tabs
                value={selectedTab}
                onChange={(e, newValue) => setSelectedTab(newValue)}
                variant="scrollable"
                scrollButtons="auto"
                sx={{
                  borderBottom: "1px solid #e0e0e0",
                  "& .MuiTab-root": {
                    textTransform: "capitalize",
                    fontWeight: 500,
                    fontSize: "0.875rem",
                  },
                  "& .Mui-selected": {
                    fontWeight: "bold",
                  },
                }}
              >
                {fraudDetectionTypes.map((type) => (
                  <Tab
                    key={type.key}
                    label={
                      <Box sx={{ display: "flex", alignItems: "center", gap: 1 }}>
                        <type.icon sx={{ fontSize: 20 }} />
                        <span>{type.label}</span>
                      </Box>
                    }
                  />
                ))}
              </Tabs>
            </Box>

            <Box sx={{ p: 3 }}>
              {fraudDetectionTypes.map((type, index) => {
                const IconComponent = type.icon;
                const count = stats.flaggedByType?.[type.key] || 0;
                const percentage = stats.totalFlagged > 0 
                  ? ((count / stats.totalFlagged) * 100).toFixed(1) 
                  : 0;

                return (
                  <Box
                    key={type.key}
                    sx={{ display: selectedTab === index ? "block" : "none" }}
                  >
                    <Grid container spacing={3}>
                      <Grid item xs={12} md={6}>
                        <Card
                          sx={{
                            borderRadius: 2,
                            boxShadow: 1,
                            height: "100%",
                            bgcolor: "#ffffff",
                            border: "1px solid #e0e0e0",
                          }}
                        >
                          <CardContent>
                            <Box sx={{ display: "flex", alignItems: "center", mb: 3 }}>
                            <Box
                              sx={{
                                p: 2,
                                borderRadius: 2,
                                bgcolor: "#f5f5f5",
                                mr: 2,
                              }}
                            >
                              <IconComponent sx={{ fontSize: 32, color: "#757575" }} />
                            </Box>
                            <Box>
                              <Typography
                                variant='h6'
                                sx={{ fontWeight: "bold", color: "#424242" }}
                              >
                                {type.label}
                              </Typography>
                              <Typography variant='body2' color='text.secondary'>
                                Flagged Items
                              </Typography>
                            </Box>
                          </Box>
                          <Typography
                            variant='h2'
                            sx={{
                              fontWeight: "bold",
                              color: "#424242",
                              mb: 1,
                            }}
                          >
                            {count}
                          </Typography>
                          <Typography variant='body2' color='text.secondary'>
                            {percentage}% of total flagged items
                          </Typography>
                          </CardContent>
                        </Card>
                      </Grid>
                      <Grid item xs={12} md={6}>
                        <Card
                          sx={{
                            borderRadius: 2,
                            boxShadow: 1,
                            height: "100%",
                            bgcolor: "#ffffff",
                            border: "1px solid #e0e0e0",
                          }}
                        >
                          <CardContent>
                            <Typography
                              variant='subtitle1'
                              sx={{ fontWeight: "bold", color: "#424242", mb: 2 }}
                            >
                              Quick Actions
                            </Typography>
                            <Button
                              variant='contained'
                              startIcon={<Security />}
                              href={`/${type.key.replace("_", "-")}`}
                              fullWidth
                              sx={{
                                mb: 2,
                                borderRadius: 2,
                                py: 1.5,
                                bgcolor: "#1976d2",
                                "&:hover": {
                                  bgcolor: "#1565c0",
                                },
                              }}
                            >
                              View {type.label} Detection
                            </Button>
                            <Button
                              variant='outlined'
                              startIcon={<Assessment />}
                              fullWidth
                              sx={{
                                borderRadius: 2,
                                py: 1.5,
                                borderColor: "#1976d2",
                                color: "#1976d2",
                                "&:hover": {
                                  borderColor: "#1976d2",
                                  bgcolor: "#e3f2fd",
                                },
                              }}
                            >
                              View Details
                            </Button>
                          </CardContent>
                        </Card>
                      </Grid>
                    </Grid>
                  </Box>
                );
              })}
            </Box>
          </Paper>
        </Grid>
      </Grid>
    </Box>
  );
};

export default Dashboard;
